ACCOUNT='''    <!-- Customer Account Modal -->
    <div class="auth-modal" id="accountModal" role="dialog" aria-modal="true" aria-labelledby="accountModalTitle" aria-describedby="accountModalIntro" aria-hidden="true"><div class="auth-modal-content"><button type="button" class="close-modal" onclick="closeAccountModal()" aria-label="Close account">×</button><header><p class="account-kicker">KEM / Account</p><h2 id="accountModalTitle">My Account</h2><p class="account-intro" id="accountModalIntro">Your KEM profile, saved addresses and order history.</p></header><div class="account-layout"><div><section class="account-section" aria-labelledby="accountProfileTitle"><div class="account-section-header"><h3 id="accountProfileTitle">Profile</h3></div><div id="accountProfile"></div></section><section class="account-section" aria-labelledby="accountAddressesTitle"><div class="account-section-header"><h3 id="accountAddressesTitle">Saved Addresses</h3></div><div id="accountAddresses" aria-live="polite"></div></section></div><section class="account-section" aria-labelledby="accountOrdersTitle"><div class="account-section-header"><h3 id="accountOrdersTitle">Orders</h3><button type="button" class="account-refresh" onclick="loadCustomerOrders()">Refresh</button></div><div id="accountOrders" aria-live="polite" aria-busy="true"><div class="account-loading">Loading orders…</div></div></section></div><div class="account-actions"><button type="button" class="account-close" onclick="closeAccountModal()">Close</button><button type="button" class="account-logout" onclick="logoutUser()">Log Out</button></div></div></div>'''
