AUTH='''    <!-- Auth Modal -->
    <div class="auth-modal" id="authModal" role="dialog" aria-modal="true" aria-labelledby="authModalTitle" aria-describedby="authModalIntro" aria-hidden="true"><div class="auth-modal-content"><button type="button" class="close-modal" onclick="closeAuthModal()" aria-label="Close account sign in">×</button><header><p class="auth-kicker">KEM / Account</p><h2 id="authModalTitle">Account</h2><p class="auth-intro" id="authModalIntro">Sign in to view your KEM account, saved addresses and orders.</p></header><div id="authFeedback" role="status" aria-live="polite"></div><div class="auth-tabs" role="tablist" aria-label="Account access"><button type="button" class="auth-tab active" id="loginTab" role="tab" aria-selected="true" aria-controls="loginForm" onclick="switchAuthTab('login')">Login</button><button type="button" class="auth-tab" id="signupTab" role="tab" aria-selected="false" aria-controls="signupForm" onclick="switchAuthTab('signup')">Sign Up</button></div>
    <form class="auth-form active" id="loginForm" role="tabpanel" aria-labelledby="loginTab" onsubmit="handleLogin(event)"><div class="auth-input-group"><label for="loginIdentifier">Email</label><input type="email" id="loginIdentifier" placeholder="your@email.com" autocomplete="email" required></div><div class="auth-input-group"><label for="loginPassword">Password</label><input type="password" id="loginPassword" placeholder="Enter your password" autocomplete="current-password" required></div><div class="auth-forgot"><button type="button" class="auth-secondary-action" onclick="handleForgotPassword()">Forgot Password?</button></div><button type="submit" class="auth-submit">Login</button><div class="auth-divider" aria-hidden="true">OR</div><div id="googleSignInButtonLogin"><div style="text-align:center;padding:1rem;background:#f5f5f5;border:1px solid #ddd;color:#666;">Loading Google Sign-In...</div></div><div class="auth-switch">Don't have an account?<button type="button" onclick="switchAuthTab('signup')">Sign Up</button></div></form>
    <form class="auth-form" id="signupForm" role="tabpanel" aria-labelledby="signupTab" onsubmit="handleSignup(event)"><div class="auth-input-group"><label for="signupName">Full Name *</label><input type="text" id="signupName" placeholder="Your name" autocomplete="name" required></div><div class="auth-input-group"><label for="signupEmail">Email *</label><input type="email" id="signupEmail" placeholder="your@email.com" autocomplete="email" required></div><div class="auth-input-group"><label for="signupPhone">Phone Number</label><input type="tel" id="signupPhone" placeholder="+20123456789" autocomplete="tel"></div><div class="auth-input-group"><label for="signupPassword">Password *</label><input type="password" id="signupPassword" placeholder="Create a password" autocomplete="new-password" minlength="6" required></div><button type="submit" class="auth-submit">Create Account</button><div class="auth-divider" aria-hidden="true">OR</div><div id="googleSignInButtonSignup"><div style="text-align:center;padding:1rem;background:#f5f5f5;border:1px solid #ddd;color:#666;">Loading Google Sign-In...</div></div><div class="auth-switch">Already have an account?<button type="button" onclick="switchAuthTab('login')">Login</button></div></form>
    <section class="auth-reset-panel" id="resetPasswordPanel" aria-labelledby="resetPasswordTitle" hidden><h3 id="resetPasswordTitle">Reset Password</h3><p>Enter the email address for your KEM account. The existing password-reset service will send the reset email.</p><form id="resetPasswordForm" onsubmit="handlePasswordResetSubmit(event)"><div class="auth-input-group"><label for="resetEmail">Email</label><input type="email" id="resetEmail" autocomplete="email" required></div><div class="auth-reset-actions"><button type="submit" class="auth-reset-submit">Send Reset Email</button><button type="button" class="auth-reset-back" onclick="switchAuthTab('login')">Return to Login</button></div></form></section></div></div>'''
h,n=re.subn(r'    <!-- Auth Modal -->.*?(?=\n\n    <!-- Google Sign-In Modal -->)',AUTH,h,count=1,flags=re.S);assert n==1
GLOBAL='''        // Auth Modal Functions (Global)
        let authDialogReturnFocus=null,accountDialogReturnFocus=null;
        function setAuthFeedback(message='',state='info'){const f=document.getElementById('authFeedback');if(!f)return;f.textContent=message;f.className=message?`auth-feedback-${state}`:'';f.setAttribute('role',state==='error'?'alert':'status')}
        window.openAuthModal=function(){const m=document.getElementById('authModal');if(!m)return;authDialogReturnFocus=document.activeElement&&!m.contains(document.activeElement)?document.activeElement:authDialogReturnFocus;m.classList.add('active');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';switchAuthTab('login');requestAnimationFrame(()=>document.getElementById('loginIdentifier')?.focus());if(window.googleLibraryLoaded&&typeof window.initializeGoogleSignIn==='function')setTimeout(()=>window.initializeGoogleSignIn(),100)}
        window.closeAuthModal=function(){const m=document.getElementById('authModal');if(!m)return;m.classList.remove('active');m.setAttribute('aria-hidden','true');document.body.style.overflow='auto';setAuthFeedback('');const t=authDialogReturnFocus;authDialogReturnFocus=null;if(t?.isConnected)requestAnimationFrame(()=>t.focus())}
        window.switchAuthTab=function(tab){const login=tab==='login';document.getElementById('loginForm')?.classList.toggle('active',login);document.getElementById('signupForm')?.classList.toggle('active',!login);const r=document.getElementById('resetPasswordPanel');if(r)r.hidden=true;const l=document.getElementById('loginTab'),s=document.getElementById('signupTab');l?.classList.toggle('active',login);s?.classList.toggle('active',!login);l?.setAttribute('aria-selected',String(login));s?.setAttribute('aria-selected',String(!login));setAuthFeedback('')}
        function showPasswordReset(){document.getElementById('loginForm')?.classList.remove('active');document.getElementById('signupForm')?.classList.remove('active');const r=document.getElementById('resetPasswordPanel');if(r)r.hidden=false;const e=document.getElementById('loginIdentifier')?.value.trim(),i=document.getElementById('resetEmail');if(i&&e)i.value=e;setAuthFeedback('');requestAnimationFrame(()=>i?.focus())}'''
h,n=re.subn(r'        // Auth Modal Functions \(Global\).*?(?=\n        // Custom Cursor)',GLOBAL,h,count=1,flags=re.S);assert n==1
h,n=re.subn(r'\n        function switchAuthTab\(tab\) \{.*?\n        \}\n\n(?=        async function handleLogin)', '\n', h,count=1,flags=re.S);assert n==1
