RESET='''                function handleForgotPassword(){showPasswordReset()}
        async function handlePasswordResetSubmit(event){event.preventDefault();const email=document.getElementById('resetEmail').value.trim().toLowerCase();if(!email)return;setAuthFeedback('Sending password reset email…','info');try{await auth.sendPasswordResetEmail(email);setAuthFeedback('If the account exists, a password reset email has been sent.','success')}catch(error){console.error('Password reset failed:',error);setAuthFeedback('Unable to start password reset. Please check the address and try again.','error')}}'''
