ACCOUNTJS='''        function renderAccountAddresses(){const c=document.getElementById('accountAddresses');if(!c)return;const u=currentUser?.uid?users[currentUser.uid]:null,a=Array.isArray(u?.savedAddresses)?u.savedAddresses:(Array.isArray(currentUser?.savedAddresses)?currentUser.savedAddresses:[]);if(!a.length){c.innerHTML='<div class="account-empty"><strong>No saved addresses</strong><p class="account-profile-meta">Saved addresses will appear here when available on your account.</p></div>';return}c.innerHTML=a.map(x=>`<article class="account-address"><div class="account-address-head"><span class="account-address-label">${escapeHTML(x.label||'Saved address')}</span>${x.isDefault?'<span class="account-address-default">Default</span>':''}</div><div class="account-address-copy">${escapeHTML(x.address||'')}${x.houseNumber?`<br>Building: ${escapeHTML(x.houseNumber)}`:''}${x.floor?`, Floor: ${escapeHTML(x.floor)}`:''}${x.city?`<br>${escapeHTML(x.city)}`:''}${x.postal?` · ${escapeHTML(x.postal)}`:''}</div></article>`).join('')}
        async function openAccountModal(){if(!auth?.currentUser||!currentUser){openAuthModal();return}const m=document.getElementById('accountModal'),profile=document.getElementById('accountProfile');accountDialogReturnFocus=document.activeElement&&!m.contains(document.activeElement)?document.activeElement:accountDialogReturnFocus;profile.innerHTML=`<p class="account-profile-name">${escapeHTML(currentUser.name||'Customer')}</p><p class="account-profile-meta">${escapeHTML(currentUser.email||'')}</p>${currentUser.phone?`<p class="account-profile-meta">${escapeHTML(currentUser.phone)}</p>`:''}`;renderAccountAddresses();m.classList.add('active');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';requestAnimationFrame(()=>m.querySelector('.close-modal')?.focus());await loadCustomerOrders()}
        function closeAccountModal(){const m=document.getElementById('accountModal');if(!m)return;m.classList.remove('active');m.setAttribute('aria-hidden','true');document.body.style.overflow='auto';const t=accountDialogReturnFocus;accountDialogReturnFocus=null;if(t?.isConnected)requestAnimationFrame(()=>t.focus())}
        async function loadCustomerOrders(){const c=document.getElementById('accountOrders');if(!c||!cloudFunctions)return;c.setAttribute('aria-busy','true');c.innerHTML='<div class="account-loading">Loading orders…</div>';try{const f=cloudFunctions.httpsCallable('getCustomerOrders'),r=await f(),o=Array.isArray(r.data?.orders)?r.data.orders:[];if(!o.length){c.innerHTML='<div class="account-empty"><strong>No orders yet</strong><p class="account-profile-meta">Your KEM orders will appear here after checkout.</p></div>';return}c.innerHTML=o.map(x=>`<article class="account-order"><div class="account-order-head"><div><div class="account-order-id">${escapeHTML(x.id)}</div><div class="account-order-date">${escapeHTML(x.createdAt||x.date||'')}</div></div><span class="status-badge status-${escapeHTML(x.status)}">${escapeHTML(x.status)}</span></div><div class="account-order-meta"><span>${Number(x.itemCount||0)} item(s)</span><span class="account-order-total">EGP ${Number(x.total||0).toFixed(2)}</span></div></article>`).join('')}catch(error){console.error('Unable to load order history:',error);c.innerHTML='<div class="account-error" role="alert">Unable to load your orders. Please try again.</div>'}finally{c.setAttribute('aria-busy','false')}}'''
